import{_ as s,o as r,c as o,a2 as a}from"./chunks/framework.BVc2lkLk.js";const g=JSON.parse('{"title":"升级与运维","description":"部署之后的日常：同步上游升级框架、重跑引导、查构建失败、出问题时止损、换密钥和彻底删除。","frontmatter":{"description":"部署之后的日常：同步上游升级框架、重跑引导、查构建失败、出问题时止损、换密钥和彻底删除。"},"headers":[],"relativePath":"maintenance.md","filePath":"maintenance.md","lastUpdated":1790607621000}'),t={name:"maintenance.md"};function i(l,e,n,d,c,h){return r(),o("div",null,[...e[0]||(e[0]=[a(`<h1 id="升级与运维" tabindex="-1">升级与运维 <a class="header-anchor" href="#升级与运维" aria-label="Permalink to &quot;升级与运维&quot;">​</a></h1><p>部署好之后会用到的事：升级框架、重跑引导、看构建为什么失败、出问题时止损、换密钥，以及不用了怎么删干净。</p><h2 id="升级框架-同步上游" tabindex="-1">升级框架：同步上游 <a class="header-anchor" href="#升级框架-同步上游" aria-label="Permalink to &quot;升级框架：同步上游&quot;">​</a></h2><p>升级就是把你的 Fork 同步到上游：</p><ol><li>打开你 Fork 的仓库首页，文件列表上方会显示「This branch is N commits behind」。</li><li>点 <strong>Sync fork</strong>，再点 <strong>Update branch</strong>。</li></ol><p>同步产生的提交推到 main 上，Workers Builds 会自动构建并部署，几分钟后生效。同步拿到的是上游 main 的最新代码，可能比最新发布的版本还新；每个版本改了什么见 <a href="https://github.com/QFlareBot/QFlareBot/releases" target="_blank" rel="noreferrer">Releases</a>，当前跑的版本显示在面板概览页的「运行时」里。</p><p>要知道的几点：</p><ul><li><strong>面板里装的插件都还在。</strong> 构建机每次都从你机器人的 D1 读已装插件清单，和仓库里的内置插件合并后一起构建。插件钉在各自的提交上，不会跟着升级；它们会用新版框架重新编译，契约只增不改，插件不需要重新打包。</li><li><strong>数据库表结构自己升级。</strong> 运行时用到时自动建表、补字段，不用重跑引导工作流。</li><li><strong>概览页的最近事件要构建 Token 多一项权限。</strong> 事件摘要改从 Workers Logs 读之后，构建 Token 要带「Workers Observability → Edit」。更早部署的 Token 没有这一项，概览页会提示：到 Cloudflare 后台 → My Profile → API Tokens 编辑这个 Token 勾上即可，Token 的值不变，不用重新部署。不补也不影响收发消息和构建，只是看不到最近事件和 24 小时统计。</li><li><strong>只改了文档的更新不会触发构建。</strong> <code>docs/</code>、<code>templates/</code>、<code>.github/</code>、<code>scripts/</code>、<code>design-system/</code>、<code>*.md</code>、<code>LICENSE</code> 在构建的排除路径里。</li><li><strong>构建缓存会自动打开。</strong> 引导部署时就会打开；更早部署的机器人，下一次从面板触发构建时补上。它缓存下载过的依赖，装依赖快十秒左右，其余步骤不受影响。怀疑缓存出了问题（比如装依赖报文件损坏），到 Cloudflare 后台 → Workers → 你的 Worker → Settings → Build → Build cache 点 Clear Cache；不想要就在同一处关掉，之后不会再被自动打开。</li><li><strong>同步触发的构建不在面板的「构建记录」里</strong>，面板只记它自己触发的构建。这次构建的进度和日志到 Cloudflare 后台看，见下一节。</li></ul><h3 id="同步时有冲突" tabindex="-1">同步时有冲突 <a class="header-anchor" href="#同步时有冲突" aria-label="Permalink to &quot;同步时有冲突&quot;">​</a></h3><p>你自己在 Fork 里改过的文件，上游也改了同一处时，Sync fork 会提示冲突。常见的是：</p><ul><li><code>apps/seed/wrangler.jsonc</code>：为 Durable Object 插件补过 <code>migrations</code>，或者改过 Worker 名；</li><li><code>apps/seed/qqbot.manifest.json</code>：去掉过内置插件。</li></ul><p>这时<strong>别点「Discard N commits」</strong>，那会把你的改动丢掉，比如补过的 migrations 没了，下一次构建就会失败。点 <strong>Open pull request</strong>，在 GitHub 上解决冲突后合并；或者在本地合并：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> remote</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/QFlareBot/QFlareBot</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">   # 只需一次</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fetch</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> merge</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upstream/main</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    # 解决冲突后提交</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> push</span></span></code></pre></div><h3 id="升级后确认" tabindex="-1">升级后确认 <a class="header-anchor" href="#升级后确认" aria-label="Permalink to &quot;升级后确认&quot;">​</a></h3><p>打开面板，概览页能看到机器人状态、最近事件照常刷新，就说明新版本在跑。在群里发一条 <code>/sid</code> 更直接。</p><h2 id="重跑引导工作流" tabindex="-1">重跑引导工作流 <a class="header-anchor" href="#重跑引导工作流" aria-label="Permalink to &quot;重跑引导工作流&quot;">​</a></h2><p>平时升级只要同步上游。发版说明里写了「需要重跑引导」时（比如改了同步上游改不到的东西：定时触发器、部署方式），或者想把部署从头再走一遍，就再运行一次 Bootstrap 工作流，步骤和第一次一样。</p><p>重跑是安全的：</p><ul><li><strong>数据、插件、域名都不动。</strong> 资源按名字复用，KV、D1、R2 里的数据原样保留；面板里装的插件按各自钉住的版本一起重新构建；自定义域名、QQ 机器人和插件配置都不碰。</li><li><strong>新版本先过健康检查才上线。</strong> Worker 已经在的话，新版本先在预览地址检查一遍、确认 secret 没丢，通过了才切流量，不通过线上保持原来的版本（Worker 带插件的 Durable Object 时平台不提供预览地址，这一步会跳过）。切完流量再同步一次定时触发器和 workers.dev 设置。</li><li><strong>面板密码可以沿用。</strong> 网页向导第 ② 步会认出这是重跑，默认「保留原来的密码」，已登录的面板照常可用；无 UI 模式不配 <code>ADMIN_TOKEN</code> secret 就沿用 Worker 上已有的，配了就用配的值。</li><li><strong>不白花构建时长。</strong> 仓库早就连好的话第 ④ 步直接确认；构建配置没变、上次构建也成功，就不再补跑。第 ⑤ 步 Worker 上已经有构建 Token 时可以直接沿用。</li><li><strong>名字要和原来一样。</strong> 第 ② 步的 Worker 名称填了别的，会另外部署一个新的机器人，原来那个不受影响。</li></ul><h2 id="构建失败了" tabindex="-1">构建失败了 <a class="header-anchor" href="#构建失败了" aria-label="Permalink to &quot;构建失败了&quot;">​</a></h2><p>装插件、更新插件、同步上游都会触发构建。<strong>只要有一个插件构建失败，整次构建就不部署</strong>，线上保持上一次成功的版本，机器人不会因此停摆。</p><ul><li><strong>面板「插件」页</strong>：「构建记录」列出面板触发的每次构建和状态，可以一键重新构建；「未上线的改动」列出没能上线的安装 / 升级 / 卸载和每个插件的失败原因。从没装上的可以直接卸载，升级失败的可以改回线上那一版。</li><li><strong>完整日志</strong>：面板里还看不到完整构建日志。到 Cloudflare 后台进入你的 Worker（默认叫 <code>qqbot</code>），在构建历史里点开那次构建。</li></ul><p>失败的条目会一直留在清单里，之后的每次构建都会带上它、每次都失败，所以要处理掉：卸载、改回旧版，或者等插件作者修好后再更新。</p><h2 id="出问题时止损" tabindex="-1">出问题时止损 <a class="header-anchor" href="#出问题时止损" aria-label="Permalink to &quot;出问题时止损&quot;">​</a></h2><p><strong>安全模式</strong>：面板「设置 → 运行时 → 安全模式」。打开后所有插件都不再处理消息和定时任务（按键回调仍会自动回应，客户端不会一直转圈），面板照常可用。它不触发构建，一分钟内全部生效。某个插件把机器人搞坏了、又不确定是哪个时先开它，再在「插件」页逐个关掉排查。</p><p><strong>回滚</strong>，从轻到重：</p><ul><li><strong>单个插件</strong>：「未上线的改动」里改回线上那一版，或在插件列表里关掉它。</li><li><strong>整个 Worker</strong>：Cloudflare 后台 Worker 的部署历史里把流量切回之前的版本。这是临时手段：下一次构建还会按 D1 清单和仓库的最新代码重新部署。</li><li><strong>框架本身</strong>：升级后出问题，在 Fork 上 <code>git revert</code> 同步进来的提交并推送，会按回退后的代码重新构建。</li></ul><h2 id="换密钥" tabindex="-1">换密钥 <a class="header-anchor" href="#换密钥" aria-label="Permalink to &quot;换密钥&quot;">​</a></h2><p><strong>面板登录密钥 <code>ADMIN_TOKEN</code></strong>：在 Cloudflare 后台 Worker 的 <strong>Settings → Variables and Secrets</strong> 里改，或者本地 <code>wrangler secret put ADMIN_TOKEN</code>。改完之后所有已登录的面板会话、插件页面的令牌立即失效，用新密钥重新登录即可。重跑 Bootstrap 工作流时选了「设一个新密码」（无 UI 模式是配了 <code>ADMIN_TOKEN</code> secret），也会用这次的值覆盖它；选沿用就不动。</p><p><strong>QQ 机器人的 AppSecret</strong>：在 QQ 开放平台重置之后，旧的就不能用了，回面板「设置」重新填入保存。</p><p><strong>构建令牌 <code>BUILD_TOKEN</code></strong>：构建机拉插件清单用的，Worker 和构建环境各存一份（构建环境里叫 <code>MANIFEST_TOKEN</code>），两边要一起改，只改一边构建会 401。一般没必要换，步骤见 <a href="https://github.com/QFlareBot/QFlareBot/blob/main/apps/seed/README.md#%E8%87%AA%E9%83%A8%E7%BD%B2worker-%E8%A7%A6%E5%8F%91-workers-builds" target="_blank" rel="noreferrer">apps/seed/README.md</a>。</p><h2 id="免费版额度" tabindex="-1">免费版额度 <a class="header-anchor" href="#免费版额度" aria-label="Permalink to &quot;免费版额度&quot;">​</a></h2><p>整个机器人（框架加所有插件）共用一份 Workers 免费额度。个人用、几个群的量一般够用，要留意的是：</p><ul><li><strong>Worker 请求每天 10 万次</strong>（UTC 0 点，即北京时间早上 8 点重置）。每条推给机器人的消息算一次，框架的定时任务每分钟一次、一天先占 1,440 次。群里开了「获取群内全部消息」之后，每条群消息都算，活跃群会涨得很快。</li><li><strong>KV 每天只能写 1,000 次</strong>。每条消息都写 KV 的插件（签到、积分）几个群就能把它打满，之后当天的写入都会失败。</li><li><strong>每次处理只有 10 ms CPU</strong>。插件做了重活（大图处理、大 JSON）会偶发报错，表现是机器人时有时无地不回。</li></ul><p>真到量了就升级 Workers 付费版。每项数字和写插件时的注意事项见<a href="./plugin-guide#_9-平台限额-免费版的硬预算">插件开发指南 · 平台限额</a>。</p><h2 id="安全" tabindex="-1">安全 <a class="header-anchor" href="#安全" aria-label="Permalink to &quot;安全&quot;">​</a></h2><ul><li><strong>装的插件就是可信代码</strong>：插件和框架跑在同一个 Worker 里，没有沙箱，<code>permissions</code> 只是告知。装之前看一眼仓库，插件目录也不做安全审核。</li><li><strong>有条件的话，机器人单开一个 Cloudflare 账号</strong>，和你别的站点、数据隔开。注意回调用的域名也得托管在这个账号下。</li><li><code>ADMIN_TOKEN</code> 用足够长的随机字符串，别和别的密码共用。</li></ul><h2 id="彻底删除" tabindex="-1">彻底删除 <a class="header-anchor" href="#彻底删除" aria-label="Permalink to &quot;彻底删除&quot;">​</a></h2><p>引导时没改过名字的话，资源都叫 <code>qqbot</code>：</p><ol><li>Cloudflare 后台 Worker <code>qqbot</code> 的 <strong>Settings → Domains &amp; Routes</strong> 里删掉自定义域名，再删除 Worker。</li><li>删掉 KV 命名空间 <code>qqbot</code>、D1 数据库 <code>qqbot</code>、R2 桶 <code>qqbot-artifacts</code>（没激活 R2 的没有这个桶）。</li><li>Cloudflare <strong>My Profile → API Tokens</strong> 里删掉引导时创建的 token。</li><li>QQ 开放平台删掉机器人，或者清空回调地址。</li><li>最后删掉 GitHub 上的 Fork。</li></ol>`,40)])])}const k=s(t,[["render",i]]);export{g as __pageData,k as default};
